    43	enum class VC5Tag : int16_t {
    44	  NoTag = 0x0, // synthetic, not an actual tag
    45	
    46	  ChannelCount = 0x000c,
    47	  ImageWidth = 0x0014,
    48	  ImageHeight = 0x0015,
    49	  LowpassPrecision = 0x0023,
    50	  SubbandCount = 0x000E,
    51	  SubbandNumber = 0x0030,
    52	  Quantization = 0x0035,
    53	  ChannelNumber = 0x003e,
    54	  ImageFormat = 0x0054,
    55	  MaxBitsPerComponent = 0x0066,
    56	  PatternWidth = 0x006a,
    57	  PatternHeight = 0x006b,
    58	  ComponentsPerSample = 0x006c,
    59	  PrescaleShift = 0x006d,
    60	
    61	  LARGE_CHUNK = 0x2000,
    62	  SMALL_CHUNK = 0x4000,
    63	  UniqueImageIdentifier = 0x4004,
    64	  LargeCodeblock = 0x6000,
    65	
    66	  Optional = int16_t(0x8000U), // only signbit set
    67	};
    68	inline VC5Tag operator&(VC5Tag LHS, VC5Tag RHS) {
    69	  using value_type = std::underlying_type<VC5Tag>::type;
    70	  return static_cast<VC5Tag>(static_cast<value_type>(LHS) &
    71	                             static_cast<value_type>(RHS));
    72	}
    73	inline bool matches(VC5Tag LHS, VC5Tag RHS) {
    74	  // Are there any common bit set?
    75	  return (LHS & RHS) != VC5Tag::NoTag;
    76	}
    77	inline bool is(VC5Tag LHS, VC5Tag RHS) {
    78	  // Does LHS have all the RHS bits set?
    79	  return (LHS & RHS) == RHS;
    80	}
    81	inline VC5Tag operator-(VC5Tag tag) {
    82	  using value_type = std::underlying_type<VC5Tag>::type;
    83	  // Negate
    84	  return static_cast<VC5Tag>(-static_cast<value_type>(tag));
    85	}
